// Config global del bot.
// El alias map de acá es fallback: el flujo de Construir alias map mergea
// las pestañas reales del Sheet + la hoja 'Aliases' al final de Config.
const config = {
  groupJid: '120363039852043503@g.us',
  spreadsheetId: '1dLd0fgqVrDLliq4sCdVxMtXdavWuREkEeZcODDk-t8Y',
  evolutionApiUrl: 'https://evolutioapi-evolution-api.mknton.easypanel.host',
  evolutionInstance: 'winndia-bot',
  // Pestañas a IGNORAR cuando auto-mapeamos por nombre de pestaña
  excludedTabs: ['NOS DEBEN', 'CHEQUES', 'Pendientes', 'REMITO BASE', 'Aliases'],
  clientAliases: {
    'ramiro rendon': 'ROCAS RAMIRO',
    'ramiro rendón': 'ROCAS RAMIRO',
    'rodriguez rendon ramiro': 'ROCAS RAMIRO',
    'mili': 'MILI CHASCOMUS',
    'milagros': 'MILI CHASCOMUS',
    'milagros gonzalez': 'MILI CHASCOMUS',
    'mili chascomus': 'MILI CHASCOMUS'
  }
};

const webhookInput = $input.first().json;
const original = webhookInput.body || webhookInput;

return [{ json: { config, original } }];

// Construye el alias map final mergeando:
// 1. clientAliases hardcodeados en Config (variantes / sinónimos)
// 2. Cada pestaña del Sheet como self-alias (lowercase -> nombre exacto)
// 3. Hoja 'Aliases' del Sheet (toma precedencia)
// También guarda tabIds: { 'Pendientes': numericId, ... } necesario para
// borrar filas via batchUpdate (deleteDimension necesita sheetId numérico).
const cfgInput = $('Config').first().json;
const config = cfgInput.config;
const original = cfgInput.original;

const tabsResp = $('Listar pestañas del Sheet').first().json;
const aliasResp = $input.first().json;

const merged = { ...config.clientAliases };
const tabIds = {};

const excluded = new Set(config.excludedTabs || []);
const tabs = (tabsResp && tabsResp.sheets) || [];
for (const t of tabs) {
  const title = t.properties && t.properties.title;
  const sheetId = t.properties && t.properties.sheetId;
  if (!title) continue;
  if (sheetId !== undefined && sheetId !== null) tabIds[title] = sheetId;
  if (excluded.has(title)) continue;
  merged[title.toLowerCase()] = title;
}

const aliasRows = (aliasResp && Array.isArray(aliasResp.values)) ? aliasResp.values.slice(1) : [];
for (const row of aliasRows) {
  if (!Array.isArray(row)) continue;
  const alias = (row[0] || '').trim().toLowerCase();
  const sheetName = (row[1] || '').trim();
  if (alias && sheetName) merged[alias] = sheetName;
}

return [{
  json: {
    config: { ...config, clientAliases: merged, tabIds },
    original
  }
}];

// Parseamos respuesta de Claude, matcheamos cliente y decidimos acción
const claudeResp = $input.first().json;
const rawText = claudeResp.content?.[0]?.text || '{}';

let extracted;
try {
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  extracted = JSON.parse(cleaned);
} catch (e) {
  extracted = { tipo: 'irrelevante', faltante: 'No se pudo parsear: ' + rawText.slice(0, 100), confianza: 'baja' };
}

const configItem = $('Construir alias map').first().json;
const aliases = configItem.config.clientAliases;
const original = configItem.original;

if (extracted.tipo === 'irrelevante') {
  return [{
    json: {
      extracted,
      accion: 'ignorar',
      config: configItem.config,
      groupJid: configItem.config.groupJid
    }
  }];
}

const esRemito = extracted.tipo === 'remito_cta1' || extracted.tipo === 'remito_cta2';
const esNDC = extracted.tipo === 'ndc_cta1' || extracted.tipo === 'ndc_cta2';
const esTransferencia = extracted.tipo === 'pago_transferencia';
const esCheque = extracted.tipo === 'pago_cheque';
const esEcheq = extracted.tipo === 'pago_echeq';
const esPago = esTransferencia || esCheque || esEcheq;

let cuenta = null;
if (extracted.tipo === 'remito_cta1' || extracted.tipo === 'ndc_cta1' || esEcheq) cuenta = 1;
else if (extracted.tipo === 'remito_cta2' || extracted.tipo === 'ndc_cta2' || esCheque) cuenta = 2;

function normalize(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, '').trim();
}

let sheetName = null;
if ((esRemito || esNDC) && extracted.cliente_detectado) {
  const detected = normalize(extracted.cliente_detectado);
  for (const [alias, sheet] of Object.entries(aliases)) {
    if (detected.includes(normalize(alias)) || normalize(alias).includes(detected)) {
      sheetName = sheet;
      break;
    }
  }
}

// Multi-cheque: cuando viene una foto con varios cheques/echeqs, normalizamos
// el array de pagos en extracted.cheques_array. Esto se serializa al guardar
// el pendiente para poder expandir a N items cuando el usuario asigna cliente.
let cheques_array = null;
if ((esCheque || esEcheq) && extracted.es_multipago && Array.isArray(extracted.pagos_multiples) && extracted.pagos_multiples.length > 1) {
  cheques_array = extracted.pagos_multiples.map(p => ({
    monto: parseFloat(p.monto) || 0,
    numero_comprobante: p.numero_comprobante || p.numero || '',
    dueno_cheque: p.dueno_cheque || p.dueno || extracted.dueno_cheque || '',
    banco: p.banco || extracted.banco || '',
    fecha_cobro: p.fecha_cobro || ''
  }));
  extracted.cheques_array = cheques_array;
  // monto total a nivel raíz = suma
  extracted.monto = cheques_array.reduce((s, c) => s + c.monto, 0);
  // comprobante / dueño / fecha_cobro como listas
  extracted.numero_comprobante = cheques_array.map(c => c.numero_comprobante || '?').join(', ');
  const duenosUniq = [...new Set(cheques_array.map(c => c.dueno_cheque).filter(Boolean))];
  extracted.dueno_cheque = duenosUniq.join(', ');
}

let accion;
if (esPago) {
  accion = 'preguntar_pago';
} else if ((esRemito || esNDC) && sheetName && cuenta && extracted.monto && extracted.confianza === 'alta') {
  accion = 'cargar';
} else if (esRemito || esNDC) {
  accion = 'preguntar';
} else {
  accion = 'ignorar';
}

return [{
  json: {
    extracted,
    sheetName,
    cuenta,
    esRemito,
    esNDC,
    esTransferencia,
    esCheque,
    esEcheq,
    esPago,
    accion,
    config: configItem.config,
    senderJid: original.data.key.participant || original.data.key.remoteJid,
    messageId: original.data.key.id,
    groupJid: configItem.config.groupJid
  }
}];

// Construye la fila para escribir en la hoja Pendientes
const d = $input.first().json;
const e = d.extracted || {};
const ts = new Date().toISOString();

// Si es multi-cheque, embebemos el array en razon con un wrapper que después
// Buscar pendiente activo sabe parsear. Permite reconstruir los N cheques
// cuando el usuario asigna el cliente con un solo mensaje.
let razon = e.razon_confianza || e.faltante || '';
if (e.cheques_array && Array.isArray(e.cheques_array) && e.cheques_array.length > 1) {
  razon = `[MULTIPAGO]${JSON.stringify(e.cheques_array)}[/MULTIPAGO] ${razon}`;
}

const pendienteRow = [
  d.messageId || '',
  ts,
  e.tipo || '',
  e.cliente_detectado || '',
  d.sheetName || '',
  d.cuenta != null ? String(d.cuenta) : '',
  e.monto != null ? String(e.monto) : '',
  e.numero_comprobante || '',
  e.fecha || '',
  e.nota_corta || '',
  e.banco || '',
  e.dueno_cheque || '',
  e.fecha_cobro || '',
  'pendiente',
  razon,
  d.groupJid || ''
];

return [{ json: { ...d, pendienteRow } }];

// Arma los datos para escribir según tipo + cuenta
const d = $input.first().json;
const e = d.extracted;

const firstCol = d.cuenta === 1 ? 'H' : 'A';
const lastCol = d.cuenta === 1 ? 'L' : 'E';

let debe = '';
let haber = '';
if (d.esNDC || d.esPago) {
  haber = e.monto;
} else {
  debe = e.monto;
}

let comprobante;
if (d.esTransferencia) {
  comprobante = 'PAGO';
} else {
  comprobante = e.numero_comprobante || '';
}

let nota = e.nota_corta || '';
if (d.esNDC) {
  nota = nota ? `NDC ${nota}` : 'NDC';
}
if (d.esCheque) {
  nota = nota ? `CH ${nota}` : 'CH';
}
if (d.esEcheq) {
  nota = nota ? `ECHEQ ${nota}` : 'ECHEQ';
}

// Fecha de carga: SIEMPRE hoy en horario argentino, formato DD/M sin ceros
const fmt = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Argentina/Buenos_Aires',
  day: 'numeric',
  month: 'numeric'
});
const parts = fmt.formatToParts(new Date());
const dia = parts.find(p => p.type === 'day').value;
const mes = parts.find(p => p.type === 'month').value;
const fechaHoy = `${dia}/${mes}`;

// Para cheques/echeqs también vamos a escribir en la hoja CHEQUES
let chequesRowValues = null;
if (d.esCheque || d.esEcheq) {
  const tipoCh = d.esCheque ? 'CH' : 'ECHEQ';
  chequesRowValues = [
    fechaHoy,                       // A: FECHA
    d.sheetName || '',              // B: CLIENTE
    e.dueno_cheque || '',           // C: DUEÑO
    e.numero_comprobante || '',     // D: NRO
    e.monto || '',                  // E: MONTO
    e.fecha_cobro || '',            // F: FECHA COBRO
    tipoCh,                         // G: TIPO (CH / ECHEQ)
    'PAGO'                          // H: ESTADO (PAGO = aún no cobrado)
  ];
}

return [{
  json: {
    ...d,
    firstCol,
    lastCol,
    readRange: `${d.sheetName}!${firstCol}:${firstCol}`,
    rowValues: [fechaHoy, comprobante, nota, debe, haber],
    chequesRowValues
  }
}];

// Encuentra la última fila con valor real en la columna FECHA y devuelve
// la fila destino (siguiente). Esto evita el problema del append de
// Sheets que toma como 'llenas' celdas con formato o fórmulas que
// devuelven string vacío.
const resp = $input.first().json;
const rows = resp.values || [];

let lastDataRow = 0;
for (let i = 0; i < rows.length; i++) {
  const cell = rows[i] && rows[i][0];
  if (cell !== null && cell !== undefined && String(cell).trim() !== '') {
    lastDataRow = i + 1;
  }
}

const targetRow = lastDataRow + 1;
const prep = $('Preparar fila').first().json;

return [{
  json: {
    ...prep,
    targetRow,
    writeRange: `${prep.sheetName}!${prep.firstCol}${targetRow}:${prep.lastCol}${targetRow}`
  }
}];

// Cuando viene multi-cheque, después de IF marcar pendiente teníamos N
// items en el flujo (uno por cheque). Acá los colapsamos en uno solo con
// totales calculados, para que Borrar pendiente y WhatsApp confirmar
// corran una sola vez con el resumen.
const items = $input.all();
if (items.length === 0) return [];
if (items.length === 1) return items;

const first = items[0].json;
const totalMonto = items.reduce((s, i) => s + (parseFloat(i.json.extracted && i.json.extracted.monto) || 0), 0);
const count = items.length;

return [{
  json: {
    ...first,
    extracted: {
      ...first.extracted,
      monto: totalMonto
    },
    chequesCount: count,
    esMultipagoAgregado: true
  }
}];

