// Busca el último pendiente activo del grupo y construye el prompt
// para Claude. Armamos el prompt acá en JS (no en el JSON body del HTTP
// node) porque cualquier comilla o backslash en los campos del pendiente
// rompía el JSON del request.
const resp = $input.first().json;
const rows = resp.values || [];
const dataRows = rows.slice(1);

const configItem = $('Construir alias map').first().json;
const config = configItem.config;
const original = configItem.original;
const groupJid = config.groupJid;

let pendiente = null;
let pendienteRowIndex = -1;
let latestTs = 0;

for (let i = 0; i < dataRows.length; i++) {
  const r = dataRows[i];
  if (r[13] === 'pendiente' && r[15] === groupJid) {
    const ts = new Date(r[1]).getTime();
    if (ts > latestTs) {
      latestTs = ts;
      pendiente = {
        id: r[0],
        timestamp: r[1],
        tipo: r[2],
        cliente_detectado: r[3],
        sheet_name: r[4],
        cuenta: r[5] ? parseInt(r[5]) : null,
        monto: r[6] ? parseFloat(r[6]) : null,
        comprobante: r[7],
        fecha: r[8],
        nota: r[9],
        banco: r[10],
        dueno_cheque: r[11],
        fecha_cobro: r[12],
        status: r[13],
        razon: r[14],
        chat_jid: r[15]
      };
      pendienteRowIndex = i + 2;
    }
  }
}

// Si el pendiente trae [MULTIPAGO]...[/MULTIPAGO] en razón, parseamos el
// array para poder expandirlo cuando el usuario asigna el cliente.
if (pendiente && typeof pendiente.razon === 'string') {
  const m = pendiente.razon.match(/^\[MULTIPAGO\](.+?)\[\/MULTIPAGO\]/);
  if (m) {
    try { pendiente.cheques_array = JSON.parse(m[1]); } catch (e) {}
  }
}

const userText = original.data.message?.conversation
  || original.data.message?.extendedTextMessage?.text
  || '';

let claudePromptText = '';
if (pendiente) {
  const multiTag = (pendiente.cheques_array && pendiente.cheques_array.length > 1)
    ? ` (MULTIPAGO — ${pendiente.cheques_array.length} cheques/echeqs en una sola foto)`
    : '';
  claudePromptText = `Sos un asistente que interpreta respuestas del equipo de ventas de Winndia (zapatería) sobre documentos comerciales que quedaron pendientes de confirmación.

DOCUMENTO PENDIENTE${multiTag}:
- Tipo: ${pendiente.tipo}
- Cliente detectado por el bot: ${pendiente.cliente_detectado || 'no identificado'}
- Hoja del cliente (si se detectó): ${pendiente.sheet_name || 'no asignada'}
- Cuenta: ${pendiente.cuenta || 'sin asignar'}
- Monto: $${pendiente.monto || 'no detectado'}
- Comprobante: ${pendiente.comprobante || 'sin'}
- Banco (cheque/echeq/transferencia): ${pendiente.banco || 'sin'}
- Firmante (cheque/echeq): ${pendiente.dueno_cheque || 'sin'}
- Razón por la que quedó pendiente: ${pendiente.razon || 'sin info'}

UN MIEMBRO DEL GRUPO RESPONDIÓ:
"${userText}"

ALIASES CONOCIDOS DE CLIENTES (texto en mensajes → nombre de la hoja en el Sheet):
${JSON.stringify(config.clientAliases)}

Tu tarea: decidir qué hacer con la respuesta.

Devolvé JSON estricto sin markdown:
{
  "accion": "cargar" | "descartar" | "ignorar",
  "razon": "frase corta",
  "datos_finales": {
    "tipo": "remito_cta1|remito_cta2|ndc_cta1|ndc_cta2|pago_transferencia|pago_cheque|pago_echeq",
    "cliente_detectado": "texto",
    "sheet_name": "nombre de la hoja (debe estar en el mapa de aliases) o null",
    "cuenta": 1 | 2,
    "monto": numero,
    "numero_comprobante": "string o vacío",
    "fecha": "DD/MM o vacío",
    "nota_corta": "string o vacío"
  }
}
(o datos_finales: null si la acción es 'descartar' o 'ignorar').

REGLAS:
- 'ok' / 'si' / 'dale' / 'cargá' / 'confirmado' / 'está bien' / 'ya está' / 'tira' → CARGAR con los datos del pendiente sin modificar.
- '<cliente>' o '<cliente> cta <X>' (ej. 'NIUSTA CTA 2', 'es de Cinna') → CARGAR con cliente y cuenta corregidos.
- 'cta 1' / 'cta 2' / 'cuenta 1' solo → CARGAR con esa cuenta y resto igual.
- 'monto X' o 'son X' → CARGAR con ese monto.
- 'descartá' / 'cancelar' / 'no carguen' / 'anular' → DESCARTAR.
- Texto que no se refiere al pendiente (chat normal del grupo) → IGNORAR.
- Para PAGOS sin cliente identificado: el texto suele ser '<cliente>' o '<cliente> cta <X>'. Mapeá el cliente a sheet_name con el diccionario de aliases. Default de cuenta si no la aclaran:
  - pago_cheque → cuenta=2
  - pago_echeq → cuenta=1
  - pago_transferencia → cuenta=2
- Si dudás, IGNORAR. Mejor no cargar mal.

SOLO JSON.`;
}

return [{
  json: {
    pendiente,
    pendienteRowIndex,
    userText,
    config,
    groupJid,
    senderJid: original.data.key.participant || original.data.key.remoteJid,
    claudePromptText
  }
}];

// Parsea la respuesta de Claude y arma la estructura para Preparar fila si es cargar.
const claudeResp = $input.first().json;
const rawText = claudeResp.content?.[0]?.text || '{}';

let decision;
try {
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  decision = JSON.parse(cleaned);
} catch (e) {
  decision = { accion: 'ignorar', razon: 'No se pudo parsear: ' + rawText.slice(0, 100) };
}

const input = $('Buscar pendiente activo').first().json;
const pendiente = input.pendiente;
const pendienteRowIndex = input.pendienteRowIndex;
const config = input.config;
const groupJid = input.groupJid;

if (decision.accion !== 'cargar') {
  return [{
    json: {
      accion: decision.accion,
      razon: decision.razon,
      pendienteRowIndex,
      config,
      groupJid
    }
  }];
}

// Construir la estructura que espera Preparar fila
const df = decision.datos_finales || {};
const tipo = df.tipo || pendiente.tipo;

const esRemito = tipo === 'remito_cta1' || tipo === 'remito_cta2';
const esNDC = tipo === 'ndc_cta1' || tipo === 'ndc_cta2';
const esTransferencia = tipo === 'pago_transferencia';
const esCheque = tipo === 'pago_cheque';
const esEcheq = tipo === 'pago_echeq';
const esPago = esTransferencia || esCheque || esEcheq;

let cuenta = df.cuenta || pendiente.cuenta;
if (!cuenta) {
  if (tipo === 'remito_cta1' || tipo === 'ndc_cta1' || esEcheq) cuenta = 1;
  else if (tipo === 'remito_cta2' || tipo === 'ndc_cta2' || esCheque) cuenta = 2;
}

const sheetName = df.sheet_name || pendiente.sheet_name;
const monto = df.monto != null ? df.monto : pendiente.monto;
const comprobante = df.numero_comprobante || pendiente.comprobante || '';
const fecha = df.fecha || pendiente.fecha || '';
const notaCorta = df.nota_corta != null ? df.nota_corta : (pendiente.nota || '');
const clienteDetectado = df.cliente_detectado || pendiente.cliente_detectado || '';

// Multi-cheque: expandir en N items, uno por cheque
if (pendiente.cheques_array && Array.isArray(pendiente.cheques_array) && pendiente.cheques_array.length > 1) {
  if (!sheetName || !cuenta) {
    return [{ json: { accion: 'ignorar', razon: 'Sin cliente/cuenta para multipago', pendienteRowIndex, config, groupJid } }];
  }
  return pendiente.cheques_array.map(c => ({
    json: {
      accion: 'cargar',
      razon: decision.razon,
      extracted: {
        tipo,
        cliente_detectado: clienteDetectado,
        fecha: '',
        numero_comprobante: c.numero_comprobante || '',
        nota_corta: '',
        monto: parseFloat(c.monto) || 0,
        banco: c.banco || pendiente.banco || '',
        dueno_cheque: c.dueno_cheque || pendiente.dueno_cheque || '',
        fecha_cobro: c.fecha_cobro || ''
      },
      sheetName,
      cuenta,
      esRemito,
      esNDC,
      esTransferencia,
      esCheque,
      esEcheq,
      esPago,
      pendienteRowIndex,
      config,
      groupJid,
      messageId: pendiente.id,
      esMultipago: true
    }
  }));
}

// Si después de todo seguimos sin sheetName o sin cuenta o sin monto, ignoramos.
if (!sheetName || !cuenta || !monto) {
  return [{
    json: {
      accion: 'ignorar',
      razon: 'Datos insuficientes tras interpretar respuesta',
      pendienteRowIndex,
      config,
      groupJid
    }
  }];
}

return [{
  json: {
    accion: 'cargar',
    razon: decision.razon,
    extracted: {
      tipo,
      cliente_detectado: clienteDetectado,
      fecha,
      numero_comprobante: comprobante,
      nota_corta: notaCorta,
      monto,
      banco: pendiente.banco || '',
      dueno_cheque: pendiente.dueno_cheque || '',
      fecha_cobro: pendiente.fecha_cobro || ''
    },
    sheetName,
    cuenta,
    esRemito,
    esNDC,
    esTransferencia,
    esCheque,
    esEcheq,
    esPago,
    pendienteRowIndex,
    config,
    groupJid,
    messageId: pendiente.id
  }
}];
